/* UIKEY LABS Production Frontend Module v3.0 - App-Style Instant View Switcher (No Long Scrolling) */
(function () {
  "use strict";

  var currentLang = "en";

  // 1. Instant App-View Switcher (Switches between Home, Demos, Pricing, FAQ, and Contact without long scrolling!)
  window.switchAppView = function (viewId) {
    var panels = document.querySelectorAll(".app-view-panel");
    var topButtons = document.querySelectorAll("[data-view-target]");
    var dockButtons = document.querySelectorAll("[data-dock-target]");

    panels.forEach(function (panel) {
      if (panel.id === "view-" + viewId) {
        panel.classList.add("is-active");
      } else {
        panel.classList.remove("is-active");
      }
    });

    topButtons.forEach(function (btn) {
      var target = btn.getAttribute("data-view-target");
      if (target === viewId) {
        btn.classList.add("active");
        btn.setAttribute("aria-selected", "true");
      } else {
        btn.classList.remove("active");
        btn.setAttribute("aria-selected", "false");
      }
    });

    dockButtons.forEach(function (btn) {
      var target = btn.getAttribute("data-dock-target");
      if (target === viewId) {
        btn.classList.add("active");
      } else {
        btn.classList.remove("active");
      }
    });

    window.toggleMobileMenu(true);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // Support URL hash navigation (#demos, #pricing, #faq, #contact)
  function syncViewFromHash() {
    var hash = (window.location.hash || "").replace("#", "").toLowerCase();
    var map = {
      demos: "demos",
      pricing: "pricing",
      offers: "pricing",
      faq: "faq",
      process: "faq",
      "case-studies": "faq",
      contact: "contact"
    };
    if (map[hash]) {
      window.switchAppView(map[hash]);
    }
  }
  window.addEventListener("hashchange", syncViewFromHash);
  window.addEventListener("DOMContentLoaded", syncViewFromHash);

  // 2. Accessible Mobile Navigation Toggle
  window.toggleMobileMenu = function (forceClose) {
    var menu = document.getElementById("mobile-menu");
    var btn = document.getElementById("mobileMenuTriggerBtn");
    if (!menu || !btn) return;

    var isOpen = menu.classList.contains("is-open");
    var nextState = forceClose === true ? false : !isOpen;

    if (nextState) {
      menu.classList.add("is-open");
      btn.setAttribute("aria-expanded", "true");
      btn.setAttribute("aria-label", "Close Navigation Menu");
    } else {
      menu.classList.remove("is-open");
      btn.setAttribute("aria-expanded", "false");
      btn.setAttribute("aria-label", "Open Navigation Menu");
    }
  };

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") {
      window.toggleMobileMenu(true);
    }
  });

  // 3. Bilingual Language Toggle (English <-> Hindi/Hinglish)
  var I18N = {
    en: {
      heroBadge: "TARGET SUB-1-SECOND LOAD TIME • MOBILE-FIRST WEB ENGINEERING",
      heroTitle: "Turn Local Search & Mobile Visitors Into Daily Clients With Fast WhatsApp Lead Websites",
      heroDesc: "Select any section below to explore 9 Live Industry Demos, Website Packages, Free Shop QR Standee Maker, or connect with us on WhatsApp—without endless scrolling!",
      langBtnLabel: "🇮🇳 हिंदी / Hinglish"
    },
    hi: {
      heroBadge: "सब-1-सेकंड टारगेट लोड स्पीड • मोबाइल-फर्स्ट वेबसाइट इंजीनियरिंग",
      heroTitle: "अपने शहर के ग्राहकों को रोज़ाना WhatsApp लीड्स में बदलें — सुपर-फास्ट वेबसाइट के साथ",
      heroDesc: "नीचे किसी भी कार्ड या टैब पर क्लिक करके 9 लाइव इंडस्ट्री डेमो, वेबसाइट पैकेज, या फ्री शॉप QR तुरंत देखें — बिना लंबा स्क्रॉल किए!",
      langBtnLabel: "🇬🇧 English"
    }
  };

  window.toggleSiteLanguage = function () {
    currentLang = currentLang === "en" ? "hi" : "en";
    var copy = I18N[currentLang];
    var badgeEl = document.getElementById("heroBadgeText");
    var titleEl = document.getElementById("heroMainHeading");
    var descEl = document.getElementById("heroSubHeading");
    var langBtns = document.querySelectorAll(".lang-toggle-btn");

    if (badgeEl) badgeEl.textContent = copy.heroBadge;
    if (titleEl) titleEl.textContent = copy.heroTitle;
    if (descEl) descEl.textContent = copy.heroDesc;
    langBtns.forEach(function (b) {
      b.textContent = copy.langBtnLabel;
      b.setAttribute("aria-pressed", currentLang === "hi" ? "true" : "false");
    });
    document.documentElement.setAttribute("lang", currentLang === "hi" ? "hi" : "en");
  };

  // 4. Industry Selector Filter for Live Demo Cards
  window.filterIndustryDemos = function (category, btnEl) {
    var cards = document.querySelectorAll("[data-industry-card]");
    var buttons = document.querySelectorAll("[data-industry-filter]");

    buttons.forEach(function (b) {
      b.classList.remove("active");
      b.setAttribute("aria-pressed", "false");
    });
    if (btnEl) {
      btnEl.classList.add("active");
      btnEl.setAttribute("aria-pressed", "true");
    }

    cards.forEach(function (card) {
      var cat = card.getAttribute("data-industry-card");
      if (category === "all" || cat === category) {
        card.style.display = "flex";
      } else {
        card.style.display = "none";
      }
    });
  };

  // 5. Validated Consultation Form Handler
  var isSubmittingLead = false;

  window.handleConsultationSubmit = function (event) {
    event.preventDefault();
    if (isSubmittingLead) return;

    var nameInput = document.getElementById("leadBusinessName");
    var industryInput = document.getElementById("leadIndustrySelect");
    var phoneInput = document.getElementById("leadPhoneInput");
    var cityInput = document.getElementById("leadCityInput");
    var statusEl = document.getElementById("leadFormStatus");
    var submitBtn = document.getElementById("leadSubmitBtn");

    var name = nameInput ? nameInput.value.trim() : "";
    var industry = industryInput ? industryInput.value.trim() : "Local Business";
    var phoneRaw = phoneInput ? phoneInput.value.replace(/[^0-9]/g, "") : "";
    var city = cityInput ? cityInput.value.trim() : "";

    if (!name || name.length < 2) {
      showFormStatus(statusEl, "कृपया अपने बिज़नेस या दुकान का सही नाम दर्ज करें (Please enter a valid business name).", true);
      if (nameInput) nameInput.focus();
      return;
    }

    if (phoneRaw.length < 10) {
      showFormStatus(statusEl, "कृपया 10 अंकों का सही WhatsApp मोबाइल नंबर दर्ज करें (Please enter a valid 10-digit phone number).", true);
      if (phoneInput) phoneInput.focus();
      return;
    }

    isSubmittingLead = true;
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = "⏳ Opening WhatsApp Desk...";
    }

    showFormStatus(
      statusEl,
      "✅ धन्यवाद! अब WhatsApp कंसल्टेशन विंडो खुल रही है...",
      false
    );

    fetch("/api/lead", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        business_name: name,
        industry: industry,
        mobile: phoneRaw.slice(-10),
        city: city
      })
    }).catch(function () {});

    var waMessage =
      "नमस्ते UIKEY LABS! मैं अपनी बिज़नेस वेबसाइट के लिए Free Consultation लेना चाहता हूँ।\n\n" +
      "• Business Name: " + name + "\n" +
      "• Industry: " + industry + "\n" +
      "• Mobile: " + phoneRaw.slice(-10) + "\n" +
      (city ? "• City: " + city + "\n" : "") +
      "\nकृपया मुझे लाइव डेमो और पैकेज की जानकारी भेजें।";

    var waUrl = "https://wa.me/918770912734?text=" + encodeURIComponent(waMessage);

    setTimeout(function () {
      window.open(waUrl, "_blank", "noopener,noreferrer");
      isSubmittingLead = false;
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.textContent = "WhatsApp पर Free Consultation लें →";
      }
    }, 400);
  };

  function showFormStatus(el, message, isError) {
    if (!el) return;
    el.textContent = message;
    el.className = "form-status show " + (isError ? "error" : "success");
  }
})();
